    if(pr.k){ kslot=Math.max(kh+LH(2),hudRawW(pr.k)+LH(12)); gap=LH(10); }
    if(pr.wait) dw=LH(34);
    pw=LH(16)+kslot+gap+tw+dw+LH(16);
    x0=-pw/2; by=Math.round(a/2);
    pl=0.9+0.1*Math.sin(T*3.4);
    ctx.globalAlpha=pl;
